<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Billiards Game</title>
    <style>
        body {
            margin: 0;
            padding: 20px;
            background: #2a5a3a;
            font-family: Arial, sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            min-height: 100vh;
        }
        #container {
            text-align: center;
        }
        canvas {
            border: 4px solid #333;
            background: #2d5a2d;
            cursor: crosshair;
            margin: 20px 0;
            display: block;
            box-shadow: 0 0 10px rgba(0,0,0,0.5);
        }
        #controls {
            margin: 10px 0;
        }
        button {
            padding: 10px 20px;
            font-size: 16px;
            cursor: pointer;
            background: #4a7c4e;
            color: white;
            border: 2px solid #2a5a3a;
            border-radius: 4px;
        }
        button:hover {
            background: #5a8c5e;
        }
        #instructions {
            color: white;
            font-size: 14px;
            max-width: 600px;
            margin: 10px auto;
            text-align: left;
            background: rgba(0,0,0,0.3);
            padding: 10px;
            border-radius: 4px;
        }
        h1 {
            margin: 0 0 10px 0;
            color: white;
        }
    </style>
</head>
<body>
    <div id="container">
        <h1>Billiards</h1>
        <div id="instructions">
            <strong>How to play:</strong><br>
            • Click and drag the white ball <strong>backward</strong> to aim and set power<br>
            • Release to shoot<br>
            • Longer drag = harder shot<br>
            • Pockets are at corners and middle of long rails<br>
            • Click Reset to rack the balls
        </div>
        <canvas id="canvas"></canvas>
        <div id="controls">
            <button onclick="window.sim.reset(window.initialBalls)">Reset / Rack</button>
        </div>
    </div>

    <script>
        const sim = {
            W: 800,
            H: 400,
            R: 8,

            balls: [],
            paused: false,
            animationId: null,

            pockets: [
                { x: 0, y: 0 },
                { x: 0, y: 400 },
                { x: 800, y: 0 },
                { x: 800, y: 400 },
                { x: 400, y: 0 },
                { x: 400, y: 400 }
            ],

            pocketRadius: 12,
            friction: 0.98,

            reset(balls) {
                this.balls = balls.map(b => ({
                    x: b.x,
                    y: b.y,
                    vx: b.vx || 0,
                    vy: b.vy || 0,
                    cue: b.cue || false,
                    potted: false
                }));
                this.render();
            },

            step(dt) {
                if (this.paused) return;

                for (let ball of this.balls) {
                    if (ball.potted) continue;

                    const speed = Math.sqrt(ball.vx * ball.vx + ball.vy * ball.vy);
                    if (speed > 0.05) {
                        const decay = Math.pow(this.friction, dt);
                        ball.vx *= decay;
                        ball.vy *= decay;
                    } else {
                        ball.vx = 0;
                        ball.vy = 0;
                    }

                    ball.x += ball.vx * dt;
                    ball.y += ball.vy * dt;
                }

                for (let ball of this.balls) {
                    if (ball.potted) continue;

                    if (ball.x - this.R < 0) {
                        ball.x = this.R;
                        ball.vx = Math.abs(ball.vx);
                    }
                    if (ball.x + this.R > this.W) {
                        ball.x = this.W - this.R;
                        ball.vx = -Math.abs(ball.vx);
                    }
                    if (ball.y - this.R < 0) {
                        ball.y = this.R;
                        ball.vy = Math.abs(ball.vy);
                    }
                    if (ball.y + this.R > this.H) {
                        ball.y = this.H - this.R;
                        ball.vy = -Math.abs(ball.vy);
                    }
                }

                for (let i = 0; i < this.balls.length; i++) {
                    for (let j = i + 1; j < this.balls.length; j++) {
                        this.checkCollision(this.balls[i], this.balls[j]);
                    }
                }

                for (let ball of this.balls) {
                    if (ball.potted) continue;
                    for (let pocket of this.pockets) {
                        const dx = ball.x - pocket.x;
                        const dy = ball.y - pocket.y;
                        if (dx * dx + dy * dy < this.pocketRadius * this.pocketRadius) {
                            ball.potted = true;
                            ball.vx = 0;
                            ball.vy = 0;
                            break;
                        }
                    }
                }

                this.render();
            },

            checkCollision(b1, b2) {
                if (b1.potted || b2.potted) return;

                const dx = b2.x - b1.x;
                const dy = b2.y - b1.y;
                const distSq = dx * dx + dy * dy;
                const minDist = this.R * 2;

                if (distSq < minDist * minDist && distSq > 1e-6) {
                    const dist = Math.sqrt(distSq);
                    const nx = dx / dist;
                    const ny = dy / dist;

                    const overlap = minDist - dist;
                    b1.x -= overlap * 0.5 * nx;
                    b1.y -= overlap * 0.5 * ny;
                    b2.x += overlap * 0.5 * nx;
                    b2.y += overlap * 0.5 * ny;

                    const dvx = b1.vx - b2.vx;
                    const dvy = b1.vy - b2.vy;
                    const dvn = dvx * nx + dvy * ny;

                    if (dvn <= 0) return;

                    b1.vx -= dvn * nx;
                    b1.vy -= dvn * ny;
                    b2.vx += dvn * nx;
                    b2.vy += dvn * ny;
                }
            },

            shoot(vx, vy) {
                const cue = this.balls.find(b => b.cue && !b.potted);
                if (cue) {
                    cue.vx = vx;
                    cue.vy = vy;
                }
            },

            state() {
                return this.balls.map(b => ({
                    x: b.x,
                    y: b.y,
                    vx: b.vx,
                    vy: b.vy,
                    potted: b.potted,
                    cue: b.cue
                }));
            },

            pause() {
                this.paused = true;
                if (this.animationId) {
                    cancelAnimationFrame(this.animationId);
                    this.animationId = null;
                }
            },

            resume() {
                this.paused = false;
                this.animate();
            },

            render() {
                const canvas = document.getElementById('canvas');
                const ctx = canvas.getContext('2d');

                ctx.fillStyle = '#2d5a2d';
                ctx.fillRect(0, 0, this.W, this.H);

                const rail = 15;
                ctx.fillStyle = '#8B4513';
                ctx.fillRect(0, 0, this.W, rail);
                ctx.fillRect(0, this.H - rail, this.W, rail);
                ctx.fillRect(0, 0, rail, this.H);
                ctx.fillRect(this.W - rail, 0, rail, this.H);

                ctx.fillStyle = '#1a1a1a';
                for (let p of this.pockets) {
                    ctx.beginPath();
                    ctx.arc(p.x, p.y, this.pocketRadius, 0, Math.PI * 2);
                    ctx.fill();
                }

                for (let ball of this.balls) {
                    if (ball.potted) continue;

                    ctx.fillStyle = 'rgba(0,0,0,0.2)';
                    ctx.beginPath();
                    ctx.arc(ball.x + 2, ball.y + 2, this.R, 0, Math.PI * 2);
                    ctx.fill();

                    ctx.fillStyle = ball.cue ? '#ffffff' : '#ffdd00';
                    ctx.beginPath();
                    ctx.arc(ball.x, ball.y, this.R, 0, Math.PI * 2);
                    ctx.fill();

                    ctx.fillStyle = 'rgba(255,255,255,0.6)';
                    ctx.beginPath();
                    ctx.arc(ball.x - this.R * 0.3, ball.y - this.R * 0.3, this.R * 0.4, 0, Math.PI * 2);
                    ctx.fill();

                    ctx.strokeStyle = 'rgba(0,0,0,0.3)';
                    ctx.lineWidth = 1;
                    ctx.beginPath();
                    ctx.arc(ball.x, ball.y, this.R, 0, Math.PI * 2);
                    ctx.stroke();
                }
            },

            animate() {
                this.step(1 / 60);
                this.animationId = requestAnimationFrame(() => this.animate());
            },

            start() {
                this.animate();
            }
        };

        const initialBalls = [
            { x: 120, y: 200, vx: 0, vy: 0, cue: true },
            { x: 650, y: 200, vx: 0, vy: 0 },
            { x: 675, y: 185, vx: 0, vy: 0 },
            { x: 675, y: 215, vx: 0, vy: 0 },
            { x: 700, y: 170, vx: 0, vy: 0 },
            { x: 700, y: 200, vx: 0, vy: 0 },
            { x: 700, y: 230, vx: 0, vy: 0 },
            { x: 725, y: 155, vx: 0, vy: 0 },
            { x: 725, y: 185, vx: 0, vy: 0 },
            { x: 725, y: 215, vx: 0, vy: 0 },
            { x: 725, y: 245, vx: 0, vy: 0 },
            { x: 750, y: 140, vx: 0, vy: 0 },
            { x: 750, y: 170, vx: 0, vy: 0 },
            { x: 750, y: 200, vx: 0, vy: 0 },
            { x: 750, y: 230, vx: 0, vy: 0 },
            { x: 750, y: 260, vx: 0, vy: 0 }
        ];

        window.sim = sim;
        window.initialBalls = initialBalls;

        const canvas = document.getElementById('canvas');
        canvas.width = sim.W;
        canvas.height = sim.H;

        let dragging = false;
        let dragX = 0;
        let dragY = 0;

        canvas.addEventListener('mousedown', (e) => {
            const rect = canvas.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            const cue = sim.balls.find(b => b.cue && !b.potted);
            if (cue) {
                const dx = x - cue.x;
                const dy = y - cue.y;
                if (dx * dx + dy * dy < (sim.R * 3) * (sim.R * 3)) {
                    dragging = true;
                    dragX = x;
                    dragY = y;
                }
            }
        });

        canvas.addEventListener('mousemove', (e) => {
            if (!dragging) return;

            const rect = canvas.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            sim.render();

            const cue = sim.balls.find(b => b.cue && !b.potted);
            if (cue) {
                const ctx = canvas.getContext('2d');

                ctx.strokeStyle = 'rgba(255,255,255,0.4)';
                ctx.lineWidth = 2;
                ctx.setLineDash([5, 5]);
                ctx.beginPath();
                ctx.moveTo(x, y);
                ctx.lineTo(cue.x, cue.y);
                ctx.stroke();
                ctx.setLineDash([]);

                const dx = cue.x - x;
                const dy = cue.y - y;
                const len = Math.sqrt(dx * dx + dy * dy);
                if (len > 0) {
                    const drawLen = Math.min(len, 300);
                    const nx = dx / len;
                    const ny = dy / len;

                    ctx.strokeStyle = 'rgba(150,200,255,0.8)';
                    ctx.lineWidth = 3;
                    ctx.beginPath();
                    ctx.moveTo(cue.x, cue.y);
                    ctx.lineTo(cue.x + nx * drawLen, cue.y + ny * drawLen);
                    ctx.stroke();
                }
            }
        });

        canvas.addEventListener('mouseup', (e) => {
            if (!dragging) return;
            dragging = false;

            const rect = canvas.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            const cue = sim.balls.find(b => b.cue && !b.potted);
            if (cue) {
                const dx = cue.x - x;
                const dy = cue.y - y;
                const len = Math.sqrt(dx * dx + dy * dy);

                if (len > 5) {
                    const power = Math.min(len, 250);
                    const vx = (dx / len) * power * 1.5;
                    const vy = (dy / len) * power * 1.5;
                    sim.shoot(vx, vy);
                }
            }

            sim.render();
        });

        sim.reset(initialBalls);
        sim.start();
    </script>
</body>
</html>
